const body = $json.body || $json;
const out = [];
function normText(s){return String(s||'').trim().toLowerCase().replace(/[?!.,।'"“”‘’()[\]{}:;]+/g,' ').replace(/\s+/g,' ').trim();}
function pushEvent(e){
  if(!e || !e.externalAccountId || !e.customerExternalId || !e.messageId) return;
  const message=String(e.message||'').trim();
  out.push({json:{...e,message,timestamp:Number(e.timestamp||Date.now()),normalizedQuestion:normText(message)}});
}
if(body.object==='whatsapp_business_account'){
  for(const entry of body.entry||[]) for(const ch of entry.changes||[]){
    const v=ch.value||{};
    if(v.statuses && !v.messages) continue;
    const externalAccountId=String(v.metadata?.phone_number_id||'');
    for(const m of v.messages||[]){
      let message='',mediaId='',type=m.type||'unknown';
      if(type==='text') message=m.text?.body||'';
      else if(type==='button') message=m.button?.text||m.button?.payload||'';
      else if(type==='interactive') message=m.interactive?.button_reply?.title||m.interactive?.button_reply?.id||m.interactive?.list_reply?.title||m.interactive?.list_reply?.id||'';
      else if(type==='image'){message=m.image?.caption||'';mediaId=m.image?.id||'';}
      else if(type==='audio') mediaId=m.audio?.id||'';
      else if(type==='document'){message=m.document?.caption||'';mediaId=m.document?.id||'';}
      pushEvent({eventKind:'customer_inbound',platform:'whatsapp',externalAccountId,customerExternalId:String(m.from||''),messageId:String(m.id||''),messageType:type,message,mediaId,mediaUrl:'',timestamp:m.timestamp?Number(m.timestamp)*1000:Date.now(),isEcho:false});
    }
  }
}else if(body.object==='page' || body.object==='instagram'){
  const platform=body.object==='instagram'?'instagram':'facebook';
  for(const entry of body.entry||[]) for(const ev of entry.messaging||[]){
    if(ev.delivery||ev.read) continue;
    if(!ev.message && !ev.postback) continue;
    const attachment=ev.message?.attachments?.[0];
    let type='text';
    if(ev.postback) type='postback';
    else if(attachment?.type==='image') type='image';
    else if(attachment?.type==='audio') type='audio';
    else if(attachment?.type) type=attachment.type;
    const text=ev.message?.text||ev.message?.quick_reply?.payload||ev.postback?.payload||'';
    const isEcho=!!ev.message?.is_echo;
    pushEvent({
      eventKind:isEcho?'page_outgoing':'customer_inbound',
      platform,
      externalAccountId:String(isEcho ? (ev.sender?.id||entry.id||'') : (ev.recipient?.id||entry.id||'')),
      customerExternalId:String(isEcho ? (ev.recipient?.id||'') : (ev.sender?.id||'')),
      messageId:String(ev.message?.mid||`${platform}:${ev.timestamp||Date.now()}:${isEcho?(ev.recipient?.id||''):(ev.sender?.id||'')}`),
      messageType:type,message:text,mediaId:'',mediaUrl:String(attachment?.payload?.url||''),timestamp:Number(ev.timestamp||Date.now()),isEcho
    });
  }
}
return out;

