const ctx=$('05M.04 - Catalog Account Context').item.json;
if(ctx.skipMigration)return[{json:{...ctx,legacyDetected:false,canonicalRows:[]}}];
const values=$json.values||[];
if(values.length===0)return[{json:{...ctx,legacyDetected:false,canonicalRows:[]}}];
const headers=values[0].map(x=>String(x||'').trim());
const canonical=["Product ID", "Product Name", "Category", "Subcategory", "Price", "Currency", "Product Description", "Product Image", "Stock Status", "Stock Qty", "Color", "Size", "Offer", "Discount", "Aliases", "Active", "Updated At"];
const recognized=new Set(['Product ID','Product Name','Name','Product','Category','Subcategory','Price','Price (৳)','Price(৳)','মূল্য','Currency','Product Description','Description','Product Image','Image','Image URL','Photo','Stock Status','Stock','Stock Qty','Quantity','Qty','Color','Size','Offer','Discount','Aliases','Active','Updated At']);
const recognizedCount=headers.filter(h=>recognized.has(h)).length;
const exact=canonical.every((h,i)=>headers[i]===h)&&headers.length>=canonical.length;
const legacyDetected=!exact && recognizedCount>=2 && values.length>1;
const idx=Object.fromEntries(headers.map((h,i)=>[h,i]));
const get=(r,...names)=>{for(const n of names){const i=idx[n];if(i!==undefined&&r[i]!==undefined&&String(r[i]).trim()!=='')return r[i];}return '';};
const num=v=>{if(v===null||v===undefined||v==='')return '';const s=String(v).replace(/[৳,\s]/g,'');const n=Number(s);return Number.isFinite(n)?n:'';};
const bool=v=>{if(v==='')return 'TRUE';return ['false','0','no','off'].includes(String(v).toLowerCase())?'FALSE':'TRUE';};
const norm=[];const seen=new Set();
for(const r of values.slice(1)){
 const name=String(get(r,'Product Name','Name','Product')).trim();if(!name)continue;
 const price=num(get(r,'Price','Price (৳)','Price(৳)','মূল্য'));
 let category=String(get(r,'Category')).trim();const desc=String(get(r,'Product Description','Description')).trim();
 if(!category){const s=(name+' '+desc).toLowerCase();if(/শাড়ি|শাড়ি|saree|sari/.test(s))category='Saree';else if(/shirt|t-shirt|পাঞ্জাবি|panjabi/.test(s))category='Clothing';else category='Uncategorized';}
 const id=String(get(r,'Product ID','SKU','ID')).trim()||name.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'').slice(0,80)+'-'+String(price||'na');
 const key=id+'|'+name.toLowerCase()+'|'+String(price);if(seen.has(key))continue;seen.add(key);
 norm.push([id,name,category,String(get(r,'Subcategory')).trim(),price,String(get(r,'Currency')).trim()||'BDT',desc,String(get(r,'Product Image','Image','Image URL','Photo')).trim(),String(get(r,'Stock Status','Stock')).trim(),num(get(r,'Stock Qty','Quantity','Qty')),String(get(r,'Color')).trim(),String(get(r,'Size')).trim(),String(get(r,'Offer')).trim(),String(get(r,'Discount')).trim(),String(get(r,'Aliases')).trim(),bool(get(r,'Active')),String(get(r,'Updated At')).trim()||new Date().toISOString()]);
}
norm.sort((a,b)=>String(a[2]).localeCompare(String(b[2]))||String(a[3]).localeCompare(String(b[3]))||String(a[1]).localeCompare(String(b[1])));
const stamp=new Date().toISOString().replace(/[-:T]/g,'').slice(0,14);
return[{json:{...ctx,legacyDetected,backupTitle:`Products_BACKUP_${stamp}`,canonicalRows:[canonical,...norm]}}];
